    def fmt(ops):
        lines = [str(len(ops))]
        for o in ops:
            lines.append('pop' if o is None else 'push %d %d' % o)
        return '\n'.join(lines)
    tests = [
        fmt([None]),
        fmt([(5, 1), None, None]),
        fmt([(5, 1), (7, 3), (9, 3), None, None, None, None]),
        fmt([(4, 2), (8, 1), None, (6, 2), None, None]),
        fmt([(1, 5), (2, 5), (3, 5), (4, 5), None, None, None, None]),
        fmt([(-9, -3), (10**9, 10**9), (0, -10**9), None, None, None]),
    ]
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(2):
            ops = []
            for _ in range(n):
                if rng.random() < 0.55:
                    ops.append((rng.randint(-50, 50), rng.randint(-3, 3)))
                else:
                    ops.append(None)
            ops.append(None)
            tests.append(fmt(ops))
    def big(n, pushp, pr):
        ops = []
        for _ in range(n):
            if rng.random() < pushp:
                ops.append((rng.randint(-10**9, 10**9), rng.randint(-pr, pr)))
            else:
                ops.append(None)
        ops.append(None)
        return ops
    tests.append(fmt(big(50000, 0.6, 10**9)))
    tests.append(fmt(big(200000 - 1, 0.7, 5)))
    tests.append(fmt(big(200000 - 1, 0.5, 10**9)))
    ops = [(i, 7) for i in range(100000)] + [None] * 99999
    tests.append(fmt(ops))
    return tests

